// Convert a number, possibly with a fractional part, from base src_base
// to base dst_base.
// value is an optional leading '-', then 1 to 10 digits, then optionally a
// '.' followed by 1 to 10 digits (so "1." and ".5" are not accepted).
// Digits are 0-9 then the letters a-z for 10 to 35, in either case, and
// every digit must be below src_base. Leading zeros are allowed.
// The result is the exact value of value truncated toward zero to at most
// frac_digits digits after the point, written in base dst_base with digits
// 0-9 then lowercase a-z: the integer part with no leading zeros ("0" when
// it is zero), then a '.' and the fractional digits with trailing zeros
// removed (no '.' at all when no fractional digit remains), and a '-'
// prefix only when the written result is not zero (never "-0").
// Return the string "invalid" if src_base or dst_base is outside 2..36,
// if frac_digits is negative, or if value is not of the form above.
// Examples:
//   convert_base("0.1", 10, 2, 8) == "0.00011001"
//   convert_base("-ff.8", 16, 10, 3) == "-255.5"
fn convert_base(value: Str, src_base: Int, dst_base: Int, frac_digits: Int) -> Str {
  if src_base < 2 || src_base > 36 || dst_base < 2 || dst_base > 36 || frac_digits < 0 {
    return "invalid";
  }
  let neg = starts_with(value, "-");
  let body = if neg { substr(value, 1, str_len(value)) } else { value };
  let (whole, frac, has_dot) = match split_once(body, ".") {
    Some((w, f)) => (w, f, true),
    None => (body, "", false),
  };
  let w = parse_digits(whole, src_base);
  let f = if has_dot { parse_digits(frac, src_base) } else { Some(0) };
  match (w, f) {
    (Some(wv), Some(fv)) => {
      let den = pow(src_base, str_len(frac));
      let digits = chars("0123456789abcdefghijklmnopqrstuvwxyz");
      let mut out = to_base(wv, dst_base);
      let mut rest = fv;
      let mut fd: List[Str] = [];
      while rest > 0 && len(fd) < frac_digits {
        rest = rest * dst_base;
        fd = push(fd, digits[rest / den]);
        rest = rest % den;
      }
      let kept = reverse(drop_while(reverse(fd), |d| d == "0"));
      if !is_empty(kept) {
        out = out ++ "." ++ join(kept, "");
      }
      if neg && out != "0" { "-" ++ out } else { out }
    },
    _ => "invalid",
  }
}

fn parse_digits(s: Str, base: Int) -> Option[Int] {
  let n = str_len(s);
  if n < 1 || n > 10 {
    return None;
  }
  let digits = chars("0123456789abcdefghijklmnopqrstuvwxyz");
  let mut v = 0;
  for c in chars(to_lower(s)) {
    match index_of(digits, c) {
      Some(d) if d < base => {
        v = v * base + d;
      },
      _ => {
        return None;
      },
    }
  }
  Some(v)
}
